mutation CreateProject($name: String!, $ownerId: String!) {
  createProject(name: $name, ownerId: $ownerId) {
    ...ProjectFields
    __typename
  }
}

fragment ProjectFields on Project {
  id
  name
  ownerId
  createdAt
  serviceIds
  databaseIds
  keyValueIds
  __typename
}

